import csv
import io


def parse_csv(raw_csv: str):
    previous_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2147483647)
        reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
        header = next(reader, None)
        if header is None:
            return {"columns": [], "rows": []}

        if header:
            header[0] = header[0].removeprefix("\ufeff")

        rows = list(reader)
    finally:
        csv.field_size_limit(previous_limit)

    width = max([len(header)] + [len(row) for row in rows])
    used = set(header)
    index = 1
    while len(header) < width:
        name = "extra_column_{}".format(index)
        index += 1
        if name not in used:
            header.append(name)
            used.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": header, "rows": rows}
